// 多级缓存 + 布隆过滤器 + 逻辑过期（示意）
private final Cache<Long, Product> local = Caffeine.newBuilder()
        .maximumSize(10_000).expireAfterWrite(Duration.ofSeconds(30)).build();
private final RBloomFilter<Long> bloom;            // Redisson 布隆过滤器，启动时加载所有商品 ID

public Product get(Long id) {
    if (!bloom.contains(id)) return null;                          // 防穿透
    Product p = local.getIfPresent(id);
    if (p != null) return p;                                       // 本地缓存（防雪崩兜底）
    CacheValue<Product> cv = redisGet("product:" + id);
    if (cv == null) return loadWithMutex(id);                      // 首次加载用互斥锁
    if (cv.expireAt().isBefore(Instant.now())) {                   // 逻辑过期（防击穿）
        if (tryLock("rebuild:" + id)) rebuildExecutor.submit(() -> rebuild(id));
    }
    local.put(id, cv.data());
    return cv.data();                                              // 返回旧值，不阻塞
}
